import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<String> pesanan = Arrays.asList("kopi", "teh", "kopi", "susu", "teh", "kopi");

        Map<String, Long> jumlah = pesanan.stream()
                .collect(Collectors.groupingBy(p -> p, TreeMap::new, Collectors.counting()));
        System.out.println(jumlah);

        List<String> kota = Arrays.asList("Bogor", "Solo", "Bandung", "Medan", "Blitar");
        Map<Character, List<String>> perHuruf = kota.stream()
                .collect(Collectors.groupingBy(k -> k.charAt(0), TreeMap::new, Collectors.toList()));
        System.out.println(perHuruf);
        System.out.println(perHuruf.get('B'));
    }
}

